import csv,json,sqlite3
with open('json/superpower.json') as f: sp={r['id']:r['power_name'] for r in json.load(f)['records']}
with open('csv/hero_power.csv') as f: hp=list(csv.DictReader(f))
conn=sqlite3.connect('db/superhero.db')
conn.row_factory=sqlite3.Row
c=conn.cursor()
c.execute('SELECT id, superhero_name FROM superhero')
sh={r['id']:r['superhero_name'] for r in c.fetchall()}
conn.close()
heroes=set()
for h in hp:
  if int(h['power_id'])==37:
    name=sh.get(int(h['hero_id']))
    if name: heroes.add(name)
print(sorted(heroes))

